package com.tecsup.pedido.model; import jakarta.persistence.*; import java.time.LocalDate; import java.math.BigDecimal; import java.util.ArrayList; import java.util.List;
@Entity @Table(name="pedido") public class Pedido {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private LocalDate fecha; @Column(nullable=false) private Long idCliente; @Column(nullable=false,precision=12,scale=2) private BigDecimal total=BigDecimal.ZERO; @Column(nullable=false,length=20) private String estado="REGISTRADO"; @OneToMany(mappedBy="pedido",cascade=CascadeType.ALL,orphanRemoval=true) private List<DetallePedido> detalles=new ArrayList<>(); public Long getId(){return id;}public LocalDate getFecha(){return fecha;}public void setFecha(LocalDate x){fecha=x;}public Long getIdCliente(){return idCliente;}public void setIdCliente(Long x){idCliente=x;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal x){total=x;}public String getEstado(){return estado;}public void setEstado(String x){estado=x;}public List<DetallePedido> getDetalles(){return detalles;}public void setDetalles(List<DetallePedido> x){detalles=x;}}
